#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_evolution;
uniform float amzp_mode;
uniform float amzp_palette;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
uniform float amzp_amount;
uniform float amzp_size;
uniform float amzp_softness;
uniform float amzp_brightness;
uniform float amzp_twinkle;
uniform float amzp_twinkleSpeed;
uniform float amzp_driftAngle;
uniform float amzp_driftSpeed;
uniform float amzp_turb;
uniform float amzp_filmFps;
uniform float amzp_blocks;
uniform float amzp_hairs;
uniform float amzp_scratches;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_layers;
uniform float amzp_seed;
uniform float amzp_overdrawOn;
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p, float pxk) {
        float z = max(amzp_scale * 2.0, 0.002);
        p -= amzp_position * pxk;
        p = nmRot(p, -radians(amzp_angle));
        return p / (z * max(amzp_stretch, float2(0.01)));
    }
    float2 nmStdUp(float2 d, float pxk) { float2 p = nmStd(float2(d.x, -d.y), pxk); return float2(p.x, -p.y); }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        if (int(amzp_blendMode) == 0) return f;
        if (int(amzp_blendMode) == 1) return float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        if (int(amzp_blendMode) == 2) return float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        if (int(amzp_blendMode) == 4) { float oa = max(b.a, f.a); return float4(min(b.rgb + f.rgb, float3(oa)), oa); }
        return f + b * (1.0 - f.a);
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float4 lightFx(float3 L) { L = clamp(L, 0.0, 1.0); return float4(L, max(L.r, max(L.g, L.b))); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 0.3) : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    bool inside(float2 uv) { return uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0; }
    float4 layerAt(float2 uv) { return inside(uv) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float3 hue(float h) { return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
    float hh(float x) { return fract(sin(x * 91.345 + amzp_seed * 13.7) * 43758.5453); }
    float vn1(float x) { float i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(hh(i), hh(i + 1.0), f); }
    float hs(float2 p, float k) { return fract(sin(dot(p, float2(127.1, 311.7)) + k * 74.7 + amzp_seed * 3.91) * 43758.5453); }
    float vs(float2 p) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(hs(i, 1.0), hs(i + float2(1.0, 0.0), 1.0), f.x), mix(hs(i + float2(0.0, 1.0), 1.0), hs(i + float2(1.0, 1.0), 1.0), f.x), f.y);
    }
    float3 pcol(float h) {
        if (int(amzp_palette) == 1) return mix(float3(1.0, 0.8, 0.5), float3(1.0, 0.95, 0.8), h);
        if (int(amzp_palette) == 2) return mix(float3(0.6, 0.8, 1.0), float3(0.85, 0.95, 1.0), h);
        if (int(amzp_palette) == 3) return h < 0.5 ? mix(float3(1.0, 0.45, 0.35), float3(1.0, 0.75, 0.3), h * 2.0) : mix(float3(1.0, 0.75, 0.3), float3(0.85, 0.4, 0.9), h * 2.0 - 1.0);
        if (int(amzp_palette) == 4) return mix(hue(h), float3(1.0), 0.25);
        if (int(amzp_palette) == 5) return mix(amzp_color1.rgb, amzp_color2.rgb, h);
        return mix(float3(0.9, 0.93, 1.0), float3(1.0), h);
    }
    float sdBox(float2 q, float2 b) { float2 d = abs(q) - b; return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0); }
    float segD(float2 p, float2 a, float2 b) { float2 pa = p - a, ba = b - a; float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-4), 0.0, 1.0); return length(pa - ba * h); }
    float shapeOf(float2 d, float r, int kind, float soft, float h) {
        if (kind == 1) {
            float s = length(d) / r;
            float body = 1.0 - smoothstep(1.0 - soft * 0.95, 1.0, s);
            float rim = exp(-pow((s - 0.93) / 0.06, 2.0)) * (1.0 - soft) * 0.5;
            return body * (0.45 + 0.4 * soft) + rim;
        }
        if (kind == 2) {
            float a = h * 6.2831;
            float2 q = nmRot(d, a) / r;
            float sd = sdBox(q, float2(0.5 + 0.5 * hs(float2(h, 3.0), 2.0), 0.35 + 0.4 * hs(float2(h, 5.0), 2.0)));
            float nz = (vs(d / r * 2.5 + h * 30.0) - 0.5) * 0.35;
            return (1.0 - smoothstep(-0.05, 0.25 + soft * 0.3, sd + nz)) * 0.5;
        }
        float a = h * 6.2831;
        float2 q = nmRot(d, a);
        q.y /= 0.5 + hs(float2(h, 7.0), 2.0) * 0.9;
        float s = length(q) / r + (vs(d / r * 1.8 + h * 20.0) - 0.5) * 0.45;
        float core = 1.0 - smoothstep(1.0 - soft * 0.9, 1.0, s);
        return core + exp(-s * 1.8) * 0.12 * soft;
    }
    void nmMain() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 orig = layerAt(uv);
        float px = pxs();
        float2 w = nmStdUp(uv * W - W * 0.5, px) / px;
        float sc = 1.0;
        float evo = prog(amzp_evolution);
        float sf = clamp(amzp_softness, 0.0, 1.0);
        float amt = clamp(amzp_amount, 0.0, 1.0);
        float2 dir = float2(cos(radians(amzp_driftAngle)), -sin(radians(amzp_driftAngle)));
        float3 L = float3(0.0);
        bool floating = int(amzp_mode) != 2;
        int nl = int(clamp(floor(amzp_layers + 0.5), 1.0, 6.0));
        if (floating) {
            for (int l = 0; l < 6; l++) {
                if (l >= nl) break;
                float fl = float(l);
                float dp = nl > 1 ? fl / float(nl - 1) : 0.5;
                float zs = mix(0.6, 1.7, dp);
                float zv = mix(0.45, 1.5, dp);
                float cs = (int(amzp_mode) == 0 ? 100.0 : 150.0) * sc * mix(0.8, 1.5, dp);
                float2 off = dir * evo * amzp_driftSpeed * 300.0 * zv + float2(sin(evo * 1.3 + fl * 2.1), cos(evo * 1.1 + fl * 4.3)) * amzp_turb * 25.0;
                float2 f = (w - off) / cs + float2(fl * 17.3, fl * 9.1);
                float2 ci = floor(f);
                for (int j = -1; j <= 1; j++) {
                    for (int i = -1; i <= 1; i++) {
                        float2 id = ci + float2(float(i), float(j));
                        float h0 = hs(id, 10.0 + fl);
                        float pr = amt * (int(amzp_mode) == 3 ? 0.3 : (int(amzp_mode) == 1 ? 0.7 : 1.3));
                        if (h0 > pr) continue;
                        float2 sp = (id + float2(hs(id, 20.0 + fl), hs(id, 30.0 + fl))) * cs;
                        float2 d = (f * cs - sp);
                        float hk = hs(id, 40.0 + fl);
                        int kind = 0; float rad = 0.0; float br = 1.0; float sft = sf;
                        float pick = hs(id, 50.0 + fl);
                        int mm = int(amzp_mode);
                        if (mm == 4) mm = pick < 0.5 ? 0 : (pick < 0.8 ? 1 : 3);
                        if (mm == 1) {
                            if (pick < 0.45) { kind = 1; rad = (18.0 + 40.0 * hk) * zs; br = 0.5 + 0.5 * hk; sft = clamp(sf + dp * 0.3, 0.0, 1.0); }
                            else { kind = 0; rad = (1.5 + 2.5 * hk) * zs; br = 1.0; sft = 0.25; }
                        } else if (mm == 3) {
                            kind = 1; rad = (60.0 + 90.0 * hk) * zs; br = 0.07 + 0.07 * hk; sft = clamp(0.7 + sf * 0.3, 0.0, 1.0);
                        } else {
                            kind = 0; rad = (1.5 + 3.5 * hk * hk) * zs; br = 0.55 + 0.45 * hs(id, 60.0 + fl); sft = sf * 0.8;
                            if (pick > 0.93) { kind = 1; rad = (6.0 + 10.0 * hk) * zs; br *= 0.45; sft = clamp(sf + 0.2, 0.0, 1.0); }
                        }
                        rad *= max(amzp_size, 0.01) * sc;
                        float tw = 1.0 - amzp_twinkle * 0.5 * (1.0 + sin(time * amzp_twinkleSpeed + hk * 6.2832 + fl));
                        float m = shapeOf(d, rad, kind, sft, hk);
                        L += pcol(hs(id, 70.0 + fl)) * m * br * tw * mix(0.55, 1.0, dp);
                    }
                }
            }
        }
        if (int(amzp_mode) == 2 || int(amzp_mode) == 4) {
            float fr = floor(time * max(amzp_filmFps, 1.0));
            float fa = int(amzp_mode) == 4 ? 0.45 : 1.0;
            float cs = 80.0 * sc;
            float2 f = w / cs;
            float2 ci = floor(f);
            for (int j = -1; j <= 1; j++) {
                for (int i = -1; i <= 1; i++) {
                    float2 id = ci + float2(float(i), float(j));
                    float k0 = fr * 13.7;
                    if (hs(id, 100.0 + k0) > amt * 0.7 * fa) continue;
                    float2 sp = (id + float2(hs(id, 110.0 + k0), hs(id, 120.0 + k0))) * cs;
                    float2 d = w - sp;
                    float hk = hs(id, 130.0 + k0);
                    float kb = hs(id, 140.0 + k0);
                    float m; float br;
                    if (kb < amzp_blocks * 0.4) { m = shapeOf(d, (10.0 + 30.0 * hk) * amzp_size * sc, 2, sf, hk); br = 0.25 + 0.2 * hk; }
                    else { m = shapeOf(d, (1.3 + 3.8 * hk * hk) * amzp_size * sc, 0, sf * 0.4, hk); br = 0.6 + 0.4 * hs(id, 150.0 + k0); }
                    L += pcol(hs(id, 160.0 + k0)) * m * br * fa * 1.2;
                }
            }
            float hg = floor(time * max(amzp_filmFps, 1.0) / 3.0);
            if (hs(float2(hg, 3.0), 200.0) < amzp_hairs * (int(amzp_mode) == 4 ? 0.5 : 0.8)) {
                float2 hc = (float2(hs(float2(hg, 4.0), 201.0), hs(float2(hg, 5.0), 202.0)) - 0.5) * float2(W.x, W.y) / px * 0.9;
                float ha = hs(float2(hg, 6.0), 203.0) * 6.2832;
                float hl = (70.0 + 120.0 * hs(float2(hg, 7.0), 204.0)) * sc;
                float curl = (hs(float2(hg, 8.0), 205.0) - 0.5) * 1.6;
                float2 prev = float2(0.0);
                float best = 1e9;
                for (int k = 0; k <= 12; k++) {
                    float t = float(k) / 12.0;
                    float2 pt = nmRot(float2((t - 0.5) * hl, curl * hl * 0.3 * sin(t * 5.0 + ha)), ha) + hc;
                    if (k > 0) best = min(best, segD(w, prev, pt));
                    prev = pt;
                }
                L += float3(0.9) * exp(-pow(best / (1.0 * sc), 2.0)) * 0.7;
            }
            float sg = floor(time * max(amzp_filmFps, 1.0) / 2.0);
            if (hs(float2(sg, 9.0), 210.0) < amzp_scratches * (int(amzp_mode) == 4 ? 0.5 : 0.8)) {
                float sx = (hs(float2(sg, 10.0), 211.0) - 0.5) * W.x / px;
                float y0 = (hs(float2(sg, 11.0), 212.0) - 0.5) * W.y / px;
                float sl = (200.0 + 600.0 * hs(float2(sg, 12.0), 213.0)) * sc;
                float wob = (vs(float2(w.y / (60.0 * sc), sg)) - 0.5) * 6.0;
                float dd = abs(w.x - sx - wob);
                float along = 1.0 - smoothstep(0.6, 1.0, abs(w.y - y0) / sl);
                L += float3(0.85) * (1.0 - smoothstep(0.4 * sc, 1.2 * sc, dd)) * along * (0.4 + 0.5 * vs(float2(w.y / (25.0 * sc), sg))) * 0.8;
            }
        }
        L *= max(amzp_brightness, 0.0);
        amzOutput = nmBlend(orig, nmGradMap(lightFx(L)));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
